$AB =  rac{1}{2}AC = 4x \quad (	ext{lyn van middelpunt loodreg op koord halveer koord}) \checkmark 	ext{R/O}
\ 	ext{In } 	riangle OAB: \quad OA^2 = OB^2 + AB^2 \quad (	ext{Pythagoras}) \checkmark 	ext{ Pyth}
\ OA^2 = (2x)^2 + (4x)^2 = 4x^2 + 16x^2 = 20x^2 \checkmark 	ext{ vereenvoudiging}
\ OD = OA = \sqrt{20}x = 2\sqrt{5}x \quad (	ext{radii}) \checkmark 	ext{ radius in terme van } x
\ 	ext{BD} = OD - OB = 2\sqrt{5}x - 2x = 2x(\sqrt{5} - 1) \checkmark 	ext{ antwoord}$
